module_header:
module parity_8bit (
    input [7:0] in,
    output out
);

testbench:
`timescale 1ns / 1ps

module parity_8bit_tb;

    reg [7:0] test_in;   // Input signal
    wire test_out;       // Output signal
    reg expected_out;    // Expected output for verification
    integer errors = 0;  // Error counter

    // Instantiate the module under test
    parity_8bit uut (
        .in(test_in),
        .out(test_out)
    );

    integer i;
    reg [7:0] test_vectors[0:4]; // Test cases
    reg expected_values[0:4];     // Expected results

    initial begin
        // Define test cases and expected results
        test_vectors[0] = 8'b00000000; expected_values[0] = 0; // Even parity (0 ones)
        test_vectors[1] = 8'b11111111; expected_values[1] = 0; // Even parity (8 ones)
        test_vectors[2] = 8'b00000001; expected_values[2] = 1; // Odd parity (1 one)
        test_vectors[3] = 8'b10000000; expected_values[3] = 1; // Odd parity (1 one)
        test_vectors[4] = 8'b01010101; expected_values[4] = 0; // Even parity (4 ones)

        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        for (i = 0; i < 5; i = i + 1) begin
            test_in = test_vectors[i];
            expected_out = expected_values[i];
            #10; // Wait for the output to stabilize

            if (test_out === expected_out) begin
                $display(" %b  |    %b     |   %b   |   PASS", test_in, expected_out, test_out);
            end else begin
                $display(" %b  |    %b     |   %b   |   FAIL", test_in, expected_out, test_out);
                errors = errors + 1;
            end
        end

        $display("=====================================");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");

        $finish;
    end

endmodule

module_header:
module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

testbench:
`timescale 1ns/1ps

module mux4to1_tb;
    // Testbench signals
    reg  [3:0] in;
    reg  [1:0] sel;
    wire out;
    integer errors = 0;

    // Instantiate the DUT (Device Under Test)
    mux4to1 dut (
        .in(in),
        .sel(sel),
        .out(out)
    );

    // Task to run a single test.
    task run_test;
        input [3:0] test_in;
        input [1:0] test_sel;
        reg expected;
        begin
            in  = test_in;
            sel = test_sel;
            #10;  // Wait for signal propagation.
            // Compute expected output: the selected bit of the input.
            expected = (test_sel == 2'b00) ? test_in[0] :
                       (test_sel == 2'b01) ? test_in[1] :
                       (test_sel == 2'b10) ? test_in[2] : test_in[3];

            // Display the test result.
            if (expected === out) begin
                $display(" %4b, %2b   |    %b     |   %b   |   PASS", test_in, test_sel, expected, out);
            end else begin
                $display(" %4b, %2b   |    %b     |   %b   |   FAIL", test_in, test_sel, expected, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Test Cases:
        run_test(4'b0001, 2'b00); // Expected out = in[0] = 1
        run_test(4'b0010, 2'b01); // Expected out = in[1] = 1
        run_test(4'b0100, 2'b10); // Expected out = in[2] = 1
        run_test(4'b1000, 2'b11); // Expected out = in[3] = 1
        run_test(4'b1010, 2'b10); // For in = 1010, in[2] = 0
        run_test(4'b1111, 2'b01); // For in = 1111, in[1] = 1
        run_test(4'b0110, 2'b11); // For in = 0110, in[3] = 0

        $display("=====================================");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");

        $finish;
    end
endmodule

module_header:
module majority (
    input a, b, c,
    output out
);

testbench:
`timescale 1ns/1ps

module majority_tb;

    // Declare a 3-bit test vector to iterate through all input combinations.
    reg [2:0] test_vector;
    reg a, b, c;       // Inputs to the DUT.
    wire out;          // DUT output.
    reg expected;      // Expected result.
    integer errors;    // Count the number of failed tests.
    integer i;         // Loop variable.

    // Instantiate the Device Under Test (DUT)
    majority uut (
        .a(a),
        .b(b),
        .c(c),
        .out(out)
    );

    initial begin
        errors = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Loop through all 8 combinations of the 3-bit input.
        // We'll assign a = test_vector[2], b = test_vector[1], c = test_vector[0]
        for(i = 0; i < 8; i = i + 1) begin
            test_vector = i;
            a = test_vector[2];
            b = test_vector[1];
            c = test_vector[0];
            #10; // Wait for the output to settle

            // Compute expected majority: at least two 1's => output 1.
            expected = (a & b) | (a & c) | (b & c);

            // Display the test result in the desired format.
            if(expected === out)
                $display("    %b%b%b     |    %b     |   %b   |   Pass", a, b, c, expected, out);
            else begin
                $display("    %b%b%b     |    %b     |   %b   |   Fail", a, b, c, expected, out);
                errors = errors + 1;
            end
        end

        $display("-------------------------------------");
        if(errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");

        $finish;
    end

endmodule

module_header:
module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

testbench:
`timescale 1ns/1ps
module bin_to_gray_tb;
    reg [3:0] binary;          // Test input
    wire [3:0] gray;           // Output from the design

    // Define arrays for test vectors and expected results.
    reg [3:0] test_vectors[0:7];
    reg [3:0] expected_values[0:7];

    integer i;
    integer errors;

    // Instantiate the design under test.
    bin_to_gray uut (
        .binary(binary),
        .gray(gray)
    );

    initial begin
        errors = 0;

        // Initialize test cases and corresponding expected Gray codes.
        // For a 4-bit number, gray = binary ^ (binary >> 1)
        // Example: binary = 4'b0010  -> 0010 >> 1 = 0001, 0010 XOR 0001 = 0011.
        test_vectors[0] = 4'b0000;  expected_values[0] = 4'b0000; // 0000 -> 0000
        test_vectors[1] = 4'b0001;  expected_values[1] = 4'b0001; // 0001 -> 0001
        test_vectors[2] = 4'b0010;  expected_values[2] = 4'b0011; // 0010 -> 0011
        test_vectors[3] = 4'b0011;  expected_values[3] = 4'b0010; // 0011 -> 0010
        test_vectors[4] = 4'b0100;  expected_values[4] = 4'b0110; // 0100 -> 0110
        test_vectors[5] = 4'b0101;  expected_values[5] = 4'b0111; // 0101 -> 0111
        test_vectors[6] = 4'b0110;  expected_values[6] = 4'b0101; // 0110 -> 0101
        test_vectors[7] = 4'b0111;  expected_values[7] = 4'b0100; // 0111 -> 0100

        // Display header
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Loop through test cases.
        for (i = 0; i < 8; i = i + 1) begin
            binary = test_vectors[i];
            #10;  // Wait for the output to stabilize
            if (gray === expected_values[i]) begin
                $display("   %b     |   %b    |   %b   | PASS", binary, expected_values[i], gray);
            end else begin
                $display("   %b     |   %b    |   %b   | FAIL", binary, expected_values[i], gray);
                errors = errors + 1;
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

module_header:
module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

testbench:
`timescale 1ns/1ps

module eq_comparator_tb;
    reg  [3:0] a, b;      // Inputs for the Device Under Test (DUT)
    wire equal;           // DUT output
    reg  expected;        // Expected output (1 if a equals b, 0 otherwise)
    integer errors;       // Counter for test failures
    integer i, j;         // Loop variables for iterating through test cases

    // Instantiate the DUT
    eq_comparator uut (
        .a(a),
        .b(b),
        .equal(equal)
    );

    initial begin
        errors = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Loop through all combinations of 4-bit numbers (0 to 15)
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                a = i;
                b = j;
                #10;  // Wait for the output to settle

                // Expected output: 1 if a equals b, 0 otherwise.
                expected = (a == b) ? 1'b1 : 1'b0;

                // Check if the DUT's output matches the expected value.
                if (equal === expected)
                    $display("   %04b %04b  |    %b     |   %b   |   Pass", a, b, expected, equal);
                else begin
                    $display("   %04b %04b  |    %b     |   %b   |   Fail", a, b, expected, equal);
                    errors = errors + 1;
                end
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");

        $finish;
    end
endmodule

