module_header:
module seven_segment_decoder (
    input [3:0] digit,
    output reg [6:0] segments
);

testbench:
`timescale 1ns/1ps

module seven_segment_decoder_tb;
    reg  [3:0] digit;         // Input to the DUT
    wire [6:0] segments;       // Output from the DUT
    reg  [6:0] expected;       // Expected 7-segment code
    integer errors;           // Count of errors
    integer i;                // Loop variable

    // Instantiate the DUT
    seven_segment_decoder uut (
        .digit(digit),
        .segments(segments)
    );

    // Function to calculate expected 7-segment code based on the digit.
    function [6:0] calc_expected;
        input [3:0] d;
        begin
            case (d)
                4'd0: calc_expected = 7'b1000000;
                4'd1: calc_expected = 7'b1111001;
                4'd2: calc_expected = 7'b0100100;
                4'd3: calc_expected = 7'b0110000;
                4'd4: calc_expected = 7'b0011001;
                4'd5: calc_expected = 7'b0010010;
                4'd6: calc_expected = 7'b0000010;
                4'd7: calc_expected = 7'b1111000;
                4'd8: calc_expected = 7'b0000000;
                4'd9: calc_expected = 7'b0010000;
                default: calc_expected = 7'b1111111;
            endcase
        end
    endfunction

    initial begin
        errors = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Iterate through all 16 possible 4-bit input values
        for(i = 0; i < 16; i = i + 1) begin
            digit = i;
            #10;  // Wait for the output to update
            expected = calc_expected(digit);
            if(segments === expected)
                $display("    %04b    |  %07b  | %07b |   Pass", digit, expected, segments);
            else begin
                $display("    %04b    |  %07b  | %07b |   Fail", digit, expected, segments);
                errors = errors + 1;
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");

        $finish;
    end
endmodule

