    reg [1:0] expected_state;

    // Instantiate the vending machine FSM
    vending_machine uut (
        .clk(clk),
        .reset(reset),
        .coin_inserted(coin_inserted),
        .item_selected(item_selected),
        .state(state)
    );

    // Clock generation: 10 time-unit period.
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        errors = 0;

        // Reset the system
        reset = 1;
        coin_inserted = 0;
        item_selected = 0;
        #10;
        reset = 0;

        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Coin | Item | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Test cases
        run_test(1'b0, 1'b0, 2'b00); // IDLE state
        run_test(1'b1, 1'b0, 2'b01); // COLLECTING_COINS state
        run_test(1'b1, 1'b1, 2'b10); // DISPENSING_ITEM state
        run_test(1'b0, 1'b0, 2'b00); // Return to IDLE
        run_test(1'b1, 1'b0, 2'b01); // Insert coin again
        run_test(1'b0, 1'b0, 2'b00); // Remove coin, should return to IDLE

