        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end

    // Task to verify expected state
    task run_test;
        input reg test_coin_inserted, test_item_selected;
        input [1:0] exp_state;
        begin
            coin_inserted = test_coin_inserted;
            item_selected = test_item_selected;
