            if (state === expected_state) begin
                $display("  %b   |  %b   |    %02b     |   %02b   |  PASS", coin_inserted, item_selected, expected_state, state);
            end else begin
                $display("  %b   |  %b   |    %02b     |   %02b   |  FAIL", coin_inserted, item_selected, expected_state, state);
