    output signed [7:0] out
);

testbench:
`timescale 1ns/1ps

module log2_int_tb;
    reg signed [15:0] in_0;
    wire signed [7:0] out;
    integer errors, i;
    reg signed [7:0] expected;

    // Instantiate the DUT.
    log2_int dut (
        .in_0(in_0),
        .out(out)
    );

    // Function to compute the expected integer log base 2.
    // This function scans the input from bit 15 to 0 and returns the index
    // of the first (most significant) '1'. (If x <= 0, it returns 0.)
    function signed [7:0] calc_log2;
        input signed [15:0] x;
        integer j;
        reg found;
        begin
            if (x <= 0)
                calc_log2 = 0;
            else begin
                found = 0;
                calc_log2 = 0;
                for (j = 15; j >= 0; j = j - 1) begin
                    if (!found && (x[j] == 1'b1)) begin
                        calc_log2 = j;
                        found = 1;
                    end
                end
            end
        end
    endfunction

    initial begin
        errors = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Apply a set of test vectors.
        // We test 13 cases: 0, 1, 2, 3, 4, 7, 8, 15, 16, 1023, 1024, -1, -100.
        for (i = 0; i < 13; i = i + 1) begin
            case (i)
                0: in_0 = 16'd0;
                1: in_0 = 16'd1;
                2: in_0 = 16'd2;
                3: in_0 = 16'd3;
                4: in_0 = 16'd4;
                5: in_0 = 16'd7;
                6: in_0 = 16'd8;
                7: in_0 = 16'd15;
                8: in_0 = 16'd16;
                9: in_0 = 16'd1023;
                10: in_0 = 16'd1024;
                11: in_0 = -16'sd1;
                12: in_0 = -16'sd100;
                default: in_0 = 16'd0;
            endcase
            #10;  // Allow combinational logic to settle.
            expected = calc_log2(in_0);

            if (out === expected)
                $display("   %6d   |    %3d   |  %3d   |   Pass", in_0, expected, out);
            else begin
                $display("   %6d   |    %3d   |  %3d   |   Fail", in_0, expected, out);
                errors = errors + 1;
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");

        $finish;
    end
endmodule

