    initial begin
        test_a[0] = 8'hAA;  test_b[0] = 8'h55;  // 0xAA = 10101010, 0x55 = 01010101
                                             // Expected: and = 0x00, or = 0xFF, xor = 0xFF
        test_a[1] = 8'hFF;  test_b[1] = 8'hF0;  // Expected: and = 0xF0, or = 0xFF, xor = 0x0F
        test_a[2] = 8'h00;  test_b[2] = 8'h0F;  // Expected: and = 0x00, or = 0x0F, xor = 0x0F
        test_a[3] = 8'hC3;  test_b[3] = 8'h3C;  // C3 = 11000011, 3C = 00111100
                                             // Expected: and = 8'h00, or = 8'hFF, xor = 8'hFF
        test_a[4] = 8'hF0;  test_b[4] = 8'h0F;  // Expected: and = 8'h00, or = 8'hFF, xor = 8'hFF
