        in = 8'hA5; shift = 0;
        #10;
        if (out === 8'hA5)
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Pass", in, shift, 8'hA5, out);
        else begin
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Fail", in, shift, 8'hA5, out);
            errors = errors + 1;
        end

        // Test Case 2:
        // in = 8'hA5, shift = 1.
        // Rotate left by 1: 1010_0101 becomes 0100_1011 = 8'h4B.
        in = 8'hA5; shift = 1;
        #10;
        if (out === 8'h4B)
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Pass", in, shift, 8'h4B, out);
        else begin
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Fail", in, shift, 8'h4B, out);
            errors = errors + 1;
        end

        // Test Case 3:
        // in = 8'hA5, shift = 2.
        // For 1010_0101, a rotate left by 2 moves the two MSBs to the LSB side.
        // Expected: {in[5:0], in[7:6]} = {6'b100101, 2'b10} = 8'b10010110 = 8'h96.
        in = 8'hA5; shift = 2;
        #10;
        if (out === 8'h96)
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Pass", in, shift, 8'h96, out);
        else begin
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Fail", in, shift, 8'h96, out);
            errors = errors + 1;
        end

        // Test Case 4:
        // in = 8'hFF, shift = 3.
        // For an input of all ones, the rotated result is still all ones.
        in = 8'hFF; shift = 3;
        #10;
        if (out === 8'hFF)
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Pass", in, shift, 8'hFF, out);
        else begin
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Fail", in, shift, 8'hFF, out);
            errors = errors + 1;
        end

        // Test Case 5:
        // in = 8'h80 (1000_0000), shift = 1.
        // Expected: rotate left moves the MSB to the LSB → 0000_0001 = 8'h01.
        in = 8'h80; shift = 1;
        #10;
        if (out === 8'h01)
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Pass", in, shift, 8'h01, out);
        else begin
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Fail", in, shift, 8'h01, out);
            errors = errors + 1;
        end

        // Test Case 6:
        // in = 8'h01 (0000_0001), shift = 7.
        // Expected: rotate left by 7 will move the LSB to the MSB position → 1000_0000 = 8'h80.
        in = 8'h01; shift = 7;
        #10;
        if (out === 8'h80)
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Pass", in, shift, 8'h80, out);
        else begin
            $display("   in = %02h, shift = %0d   |   %02h   | %02h  |   Fail", in, shift, 8'h80, out);
            errors = errors + 1;
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

