        @(posedge clk);
        @(posedge clk);

        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input         | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Apply a series of test cases.
        // Note: Because the adder is pipelined, the output corresponds to the inputs
        // applied two clock cycles earlier.
        for (i = 0; i < 10; i = i + 1) begin
            // Generate test vectors.
            // (You can choose any pattern; here we use a simple sequence for illustration.)
            a = i * 16'h0011;  // e.g. 0, 0x0011, 0x0022, ...
            b = i * 16'h0101;  // e.g. 0, 0x0101, 0x0202, ...
            expected = a + b;  // 16-bit addition (modulo 2^16)

            // Wait two clock cycles for the pipeline to produce the result.
            @(posedge clk);
            @(posedge clk);

            if (out === expected)
                $display("   a=%04h, b=%04h  |   %04h   |  %04h  |   Pass", a, b, expected, out);
            else begin
                $display("   a=%04h, b=%04h  |   %04h   |  %04h  |   Fail", a, b, expected, out);
