module pipelined_accumulator (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] out
);

testbench:
`timescale 1ns/1ps

module pipelined_accumulator_tb;
    reg clk, rst;
    reg [7:0] x;
    wire [15:0] out;

    integer cycle, errors;
    integer group;  // to index the expected group sum

    // Instantiate the DUT.
    pipelined_accumulator dut (
        .clk(clk),
        .rst(rst),
        .x(x),
        .out(out)
    );

    // Clock generation: 10 time-unit period.
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Define an array of test inputs.
    // We'll supply inputs for 13 clock cycles so that we can check three groups:
    //   Group 0 (cycles 0-3): 1, 2, 3, 4   -> Expected sum: 10
    //   Group 1 (cycles 4-7): 10, 20, 30, 40 -> Expected sum: 100
    //   Group 2 (cycles 8-11): 5, 5, 5, 5    -> Expected sum: 20
    // Cycle 12 is a dummy input to allow group 2's result to propagate.
    reg [7:0] test_inputs [0:12];
    initial begin
        // Group 0: cycles 0-3
        test_inputs[0]  = 8'd1;
        test_inputs[1]  = 8'd2;
        test_inputs[2]  = 8'd3;
        test_inputs[3]  = 8'd4;
        // Group 1: cycles 4-7
        test_inputs[4]  = 8'd10;
        test_inputs[5]  = 8'd20;
        test_inputs[6]  = 8'd30;
        test_inputs[7]  = 8'd40;
        // Group 2: cycles 8-11
        test_inputs[8]  = 8'd5;
        test_inputs[9]  = 8'd5;
        test_inputs[10] = 8'd5;
        test_inputs[11] = 8'd5;
        // Cycle 12: extra cycle (dummy value) to let group 2's result appear.
        test_inputs[12] = 8'd0;
    end

    // Expected group sums.
    reg [15:0] expected_sum [0:2];
    initial begin
        expected_sum[0] = 16'd10;   // 1+2+3+4 = 10
        expected_sum[1] = 16'd100;  // 10+20+30+40 = 100
        expected_sum[2] = 16'd20;   // 5+5+5+5 = 20
    end

    // Main test process.
    initial begin
        errors = 0;

        // Apply reset.
        rst = 1;
        x = 8'd0;
        #12;  // wait a bit more than one clock cycle
        rst = 0;

        // Display header.
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Drive the test inputs over 13 clock cycles.
        // Note: The design produces a valid group sum one cycle after the group is completed.
        for (cycle = 0; cycle < 13; cycle = cycle + 1) begin
            @(posedge clk);
            x = test_inputs[cycle];

            // Check the output at cycles when a group's result is expected:
            // Group 0's sum is available at cycle 4,
            // Group 1's sum at cycle 8,
            // Group 2's sum at cycle 12.
            if (cycle == 4 || cycle == 8 || cycle == 12) begin
                if (cycle == 4)
                    group = 0;
                else if (cycle == 8)
                    group = 1;
                else if (cycle == 12)
                    group = 2;

                #1;  // allow output to settle
                if (out === expected_sum[group])
                    $display("   Cycle %0d  |   %05d   |  %05d |   Pass", cycle, expected_sum[group], out);
                else begin
                    $display("   Cycle %0d  |   %05d   |  %05d |   Fail", cycle, expected_sum[group], out);
                    errors = errors + 1;
                end
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

