        .x0(x0),
        .x1(x1),
        .x2(x2),
        .x3(x3),
        .max_value(max_value)
    );

    // Clock generation: period = 10ns
    initial clk = 0;
    always #5 clk = ~clk;

    // Test case arrays (4 test cases)
