    reg [7:0] test_x1 [0:3];
    reg [7:0] test_x2 [0:3];
    reg [7:0] test_x3 [0:3];
    reg [7:0] expected [0:3];

    integer i;
    integer errors;

    initial begin
        errors = 0;
        // Initialize test vectors.
        // Test Case 0: {10, 20, 5, 15} -> Expected max = 20
        test_x0[0] = 8'd10; test_x1[0] = 8'd20; test_x2[0] = 8'd5;  test_x3[0] = 8'd15; expected[0] = 8'd200;
        // Test Case 1: {100, 50, 200, 150} -> Expected max = 200
        test_x0[1] = 8'd100; test_x1[1] = 8'd50; test_x2[1] = 8'd200; test_x3[1] = 8'd150; expected[1] = 8'd0;
        // Test Case 2: {0, 0, 0, 0} -> Expected max = 0
        test_x0[2] = 8'd0; test_x1[2] = 8'd0; test_x2[2] = 8'd0;  test_x3[2] = 8'd0; expected[2] = 8'd255;
        // Test Case 3: {255, 100, 200, 250} -> Expected max = 255
        test_x0[3] = 8'd255; test_x1[3] = 8'd100; test_x2[3] = 8'd200; test_x3[3] = 8'd250; expected[3] = 8'd255;

        // Apply reset.
