            @(negedge clk);
            x0 <= test_x0[i];
            x1 <= test_x1[i];
            x2 <= test_x2[i];
            x3 <= test_x3[i];
        end

        // After applying test vectors, drive zeros to flush the pipeline.
        x0 = 8'd0; x1 = 8'd0; x2 = 8'd0; x3 = 8'd0;

        // Wait for 4 clock cycles to capture the outputs corresponding to the test cases.
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");
        for (i = 0; i < 4; i = i + 1) begin
            @(negedge clk);
            if (max_value === expected[i]) begin
                $display(" %3d, %3d, %3d, %3d |   %3d    |   %3d  | PASS", 
                         test_x0[i], test_x1[i], test_x2[i], test_x3[i], expected[i], max_value);
            end else begin
                $display(" %3d, %3d, %3d, %3d |   %3d    |   %3d  | FAIL", 
                         test_x0[i], test_x1[i], test_x2[i], test_x3[i], expected[i], max_value);
                errors = errors + 1;
            end
        end
        $display("=====================================");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
