module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

testbench:
`timescale 1ns/1ps

module pipelined_fir_tb;
    reg clk, rst;
    reg [7:0] x;
    wire [15:0] y;

    integer cycle, errors;
    integer i;

    // Instantiate the FIR filter.
    pipelined_fir dut (
        .clk(clk),
        .rst(rst),
        .x(x),
        .y(y)
    );

    // Clock generation: period = 10 time-units.
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Define a test vector for 16 clock cycles.
    // (These values will be applied one per clock cycle.)
    reg [7:0] test_inputs [0:15];
    initial begin
        test_inputs[0]  = 8'd1;
        test_inputs[1]  = 8'd2;
        test_inputs[2]  = 8'd3;
        test_inputs[3]  = 8'd4;
        test_inputs[4]  = 8'd5;
        test_inputs[5]  = 8'd6;
        test_inputs[6]  = 8'd7;
        test_inputs[7]  = 8'd8;
        test_inputs[8]  = 8'd9;
        test_inputs[9]  = 8'd10;
        test_inputs[10] = 8'd11;
        test_inputs[11] = 8'd12;
        test_inputs[12] = 8'd13;
        test_inputs[13] = 8'd14;
        test_inputs[14] = 8'd15;
        test_inputs[15] = 8'd16;
    end

    // Pre-calculate expected outputs.
    // Because our pipeline uses shift registers and three pipelined stages,
    // the total latency is 4 clock cycles.
    // For cycles 0 to 6, the filter window is not yet full so we expect 0.
    // For cycle n (n >= 7), the expected output is:
    //   expected = 1*test_inputs[n-4] + 2*test_inputs[n-5] +
    //              3*test_inputs[n-6] + 4*test_inputs[n-7]
    reg [15:0] expected [0:15];
    initial begin
        for (i = 0; i < 7; i = i + 1) begin
            expected[i] = 16'd0;
        end
        for (i = 7; i < 16; i = i + 1) begin
            expected[i] = ( 1 * test_inputs[i-4] ) +
                          ( 2 * test_inputs[i-5] ) +
                          ( 3 * test_inputs[i-6] ) +
                          ( 4 * test_inputs[i-7] );
        end
    end

    // Main test process.
    initial begin
        errors = 0;

        // Apply reset.
        rst = 1;
        x = 8'd0;
        #12;  // Wait a little over one clock cycle.
        rst = 0;

        // Display header.
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // For each cycle, drive the test input and (after a small delay) check y.
        for (cycle = 0; cycle < 16; cycle = cycle + 1) begin
            @(posedge clk);
            x = test_inputs[cycle];
            #1;  // Allow y to settle.
            if (y === expected[cycle])
                $display("   Cycle %0d  |   %05d   |  %05d |   Pass", cycle, expected[cycle], y);
            else begin
                $display("   Cycle %0d  |   %05d   |  %05d |   Fail", cycle, expected[cycle], y);
                errors = errors + 1;
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

