        in_0 = -128;
        #10; // wait for the output to settle
        expected = (in_0 + 1) * (in_0 + 1); // (-128 + 1) * (-128 + 1) = (-127)^2 = 16129
        if (out === expected)
            $display("   %4d      |  %6d  |  %6d  |   Pass", in_0, expected, out);
        else begin
            $display("   %4d      |  %6d  |  %6d  |   Fail", in_0, expected, out);
