        #10;
        expected = (0 + 1) * (0 + 1); // 1*1 = 1
        if (out === expected)
            $display("   %4d      |  %6d  |  %6d  |   Pass", in_0, expected, out);
        else begin
            $display("   %4d      |  %6d  |  %6d  |   Fail", in_0, expected, out);
