// tb_feistel_cipher.v
// Testbench for the feistel_cipher module.
// It applies several test vectors and displays a table showing the test input,
// expected output, actual output, and whether the test passed or failed.

`timescale 1ns/1ps

module tb_feistel_cipher;

  // Testbench signals
  reg  [7:0] data_in;
  wire [7:0] data_out;

  // Instantiate the Feistel cipher (UUT)
  feistel_cipher uut (
      .data_in(data_in),
      .data_out(data_out)
  );

  integer errors;

  initial begin
    errors = 0;

    $display("==========Testbench results==========");
    $display("=====================================");
    $display(" Test Input  | Expected | Output | Pass/Fail ");
    $display("-------------------------------------");

    // Test 1:
    // data_in = 8'h00
    // L0 = 4'h0, R0 = 4'h0.
    // f_out = 0 XOR 1010 = 1010.
    // R1 = L0 XOR f_out = 0 XOR 1010 = 1010.
    // L1 = R0 = 0.
    // After swap, data_out = {R1, L1} = {1010, 0000} = 8'hA0.
    data_in = 8'h00;
    #10;
    if (data_out == 8'hA0)
      $display("    1: %h       |   A0    |  %h   | PASS", data_in, data_out);
    else begin
      $display("    1: %h       |   A0    |  %h   | FAIL", data_in, data_out);
      errors = errors + 1;
    end

    // Test 2:
    // data_in = 8'hFF
    // L0 = 4'hF, R0 = 4'hF.
    // f_out = 4'hF XOR 1010 = 4'h5 (since 1111 XOR 1010 = 0101).
    // R1 = 4'hF XOR 4'h5 = 4'hA (1111 XOR 0101 = 1010).
    // L1 = R0 = 4'hF.
    // data_out = {R1, L1} = {1010, 1111} = 8'hAF.
    data_in = 8'hFF;
    #10;
    if (data_out == 8'hAF)
      $display("    2: %h       |   AF    |  %h   | PASS", data_in, data_out);
    else begin
      $display("    2: %h       |   AF    |  %h   | FAIL", data_in, data_out);
      errors = errors + 1;
    end

    // Test 3:
    // data_in = 8'hAB  (A = 1010, B = 1011)
    // L0 = 1010, R0 = 1011.
    // f_out = 1011 XOR 1010 = 0001.
    // R1 = 1010 XOR 0001 = 1011.
    // L1 = 1011.
    // data_out = {1011, 1011} = 8'hBB.
    data_in = 8'hAB;
    #10;
    if (data_out == 8'hBB)
      $display("    3: %h       |   BB    |  %h   | PASS", data_in, data_out);
    else begin
      $display("    3: %h       |   BB    |  %h   | FAIL", data_in, data_out);
      errors = errors + 1;
    end

    // Test 4:
    // data_in = 8'h12  (1 = 0001, 2 = 0010)
    // L0 = 0001, R0 = 0010.
    // f_out = 0010 XOR 1010 = 1000.
    // R1 = 0001 XOR 1000 = 1001.
    // L1 = 0010.
    // data_out = {1001, 0010} = 8'h92.
    data_in = 8'h12;
    #10;
    if (data_out == 8'h92)
      $display("    4: %h       |   92    |  %h   | PASS", data_in, data_out);
    else begin
      $display("    4: %h       |   92    |  %h   | FAIL", data_in, data_out);
      errors = errors + 1;
    end

    // Test 5:
    // data_in = 8'h3C  (3 = 0011, C = 1100)
    // L0 = 0011, R0 = 1100.
    // f_out = 1100 XOR 1010 = 0110.
    // R1 = 0011 XOR 0110 = 0101.
    // L1 = 1100.
    // data_out = {0101, 1100} = 8'h5C.
    data_in = 8'h3C;
    #10;
    if (data_out == 8'h5C)
