    output signed [15:0] heat_index // Heat Index in Celsius
);

testbench:
`timescale 1ns/1ps
module tb_heat_index;

  // Testbench signals
  reg [7:0] temperature;
  reg [7:0] humidity;
  reg signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9;
  wire signed [15:0] heat_index;
  integer errors;

  // Instantiate the Unit Under Test (UUT)
  heat_index uut (
    .temperature(temperature),
    .humidity(humidity),
    .C1(C1),
    .C2(C2),
    .C3(C3),
    .C4(C4),
    .C5(C5),
    .C6(C6),
    .C7(C7),
    .C8(C8),
    .C9(C9),
    .heat_index(heat_index)
  );

  initial begin
    errors = 0;

    $display("==========Testbench results==========");
    $display("=====================================");
    $display(" Test Input                           | Expected | Output | Pass/Fail ");
    $display("---------------------------------------------------------------");

    // Test Case 1:
    // Use a simplified formula: heat_index = C1 + C2*T + C3*R.
    // Coefficients: C1 = -80, C2 = 11, C3 = 1; all others = 0.
    // For temperature = 30, humidity = 70:
    // Expected = -80 + (11 * 30) + 70 = -80 + 330 + 70 = 320.
    temperature = 8'd30;
    humidity = 8'd70;
    C1 = -16'sd80;
    C2 = 16'sd11;
    C3 = 16'sd1;
    C4 = 16'sd0;
    C5 = 16'sd0;
    C6 = 16'sd0;
    C7 = 16'sd0;
    C8 = 16'sd0;
    C9 = 16'sd0;
    #10;
    if (heat_index === 16'sd320)
      $display("   1: T=%3d, R=%3d           |   320   | %4d  | PASS", temperature, humidity, heat_index);
    else begin
      $display("   1: T=%3d, R=%3d           |   320   | %4d  | FAIL", temperature, humidity, heat_index);
      errors = errors + 1;
    end

    // Test Case 2:
    // Use quadratic terms: heat_index = T + R + T^2 + R^2.
    // Coefficients: C1=0, C2=1, C3=1, C5=1, C6=1; others = 0.
    // For temperature = 10, humidity = 20:
    // Expected = 10 + 20 + (10^2) + (20^2) = 10 + 20 + 100 + 400 = 530.
    temperature = 8'd10;
    humidity = 8'd20;
    C1 = 16'sd0;
    C2 = 16'sd1;
    C3 = 16'sd1;
    C4 = 16'sd0;
    C5 = 16'sd1;
    C6 = 16'sd1;
    C7 = 16'sd0;
    C8 = 16'sd0;
    C9 = 16'sd0;
    #10;
    if (heat_index === 16'sd530)
      $display("   2: T=%3d, R=%3d           |   530   | %4d  | PASS", temperature, humidity, heat_index);
    else begin
      $display("   2: T=%3d, R=%3d           |   530   | %4d  | FAIL", temperature, humidity, heat_index);
      errors = errors + 1;
    end

    // Test Case 3:
    // Use an interaction term: heat_index = 10 + 2*T + 3*R + T*R.
    // Coefficients: C1 = 10, C2 = 2, C3 = 3, C4 = 1; others = 0.
    // For temperature = 20, humidity = 30:
    // Expected = 10 + 40 + 90 + 600 = 740.
    temperature = 8'd20;
    humidity = 8'd30;
    C1 = 16'sd10;
    C2 = 16'sd2;
    C3 = 16'sd3;
    C4 = 16'sd1;
    C5 = 16'sd0;
    C6 = 16'sd0;
    C7 = 16'sd0;
    C8 = 16'sd0;
    C9 = 16'sd0;
    #10;
    if (heat_index === 16'sd740)
      $display("   3: T=%3d, R=%3d           |   740   | %4d  | PASS", temperature, humidity, heat_index);
    else begin
      $display("   3: T=%3d, R=%3d           |   740   | %4d  | FAIL", temperature, humidity, heat_index);
      errors = errors + 1;
    end

    // Test Case 4:
    // Use quadratic difference: heat_index = T^2 - R^2.
    // Coefficients: C1=0, C2=0, C3=0, C4=0, C5=1, C6=-1; others = 0.
    // For temperature = 50, humidity = 20:
    // Expected = (50^2) - (20^2) = 2500 - 400 = 2100.
    temperature = 8'd50;
    humidity = 8'd20;
    C1 = 16'sd0;
    C2 = 16'sd0;
    C3 = 16'sd0;
    C4 = 16'sd0;
    C5 = 16'sd1;
    C6 = -16'sd1;
    C7 = 16'sd0;
    C8 = 16'sd0;
    C9 = 16'sd0;
    #10;
    if (heat_index === 16'sd2100)
      $display("   4: T=%3d, R=%3d           |  2100   | %4d  | PASS", temperature, humidity, heat_index);
    else begin
      $display("   4: T=%3d, R=%3d           |  2100   | %4d  | FAIL", temperature, humidity, heat_index);
      errors = errors + 1;
    end

    // Test Case 5:
    // Use higher-order terms: heat_index = T^2*R - T*R^2 + T^2*R^2.
    // Coefficients: C1=0, C2=0, C3=0, C4=0, C5=0, C6=0, C7=1, C8=-1, C9=1.
    // For temperature = 2, humidity = 3:
    // Compute: T^2 = 4, R^2 = 9, so:
    //   T^2*R = 4*3 = 12, T*R^2 = 2*9 = 18, T^2*R^2 = 4*9 = 36.
    // Expected = 12 - 18 + 36 = 30.
    temperature = 8'd2;
    humidity = 8'd3;
    C1 = 16'sd0;
    C2 = 16'sd0;
    C3 = 16'sd0;
    C4 = 16'sd0;
    C5 = 16'sd0;
    C6 = 16'sd0;
    C7 = 16'sd1;
    C8 = -16'sd1;
    C9 = 16'sd1;
    #10;
    if (heat_index === 16'sd30)
      $display("   5: T=%3d, R=%3d           |    30   | %4d  | PASS", temperature, humidity, heat_index);
    else begin
      $display("   5: T=%3d, R=%3d           |    30   | %4d  | FAIL", temperature, humidity, heat_index);
      errors = errors + 1;
    end

    $display("---------------------------------------------------------------");
    if (errors == 0)
      $display("All tests passed");
    else
      $display("Some tests failed: %0d error(s)", errors);

    $finish;
  end

endmodule

