  reg [7:0] no2;
  // Output from the Unit Under Test (UUT).
  wire [15:0] aqi;

  // Error counter.
  integer errors;

  // Instantiate the Unit Under Test.
  air_quality_index uut (
    .pm2_5(pm2_5),
    .pm10(pm10),
    .no2(no2),
    .aqi(aqi)
  );

  initial begin
    errors = 0;

    $display("==========Testbench results==========");
    $display("=====================================");
    $display(" Test Input               | Expected | Output | Pass/Fail ");
    $display("-------------------------------------");



    // Test Case 3:
    // pm2_5 = 0, pm10 = 0, no2 = 0.
    // All terms are zero; expected AQI = 0.
    pm2_5 = 8'd0;  pm10 = 8'd0;  no2 = 8'd0;
    #10;
    if (aqi == 16'd0)
      $display("   3: PM2.5=%3d, PM10=%3d, NO2=%3d |    0    |  %3d   | PASS", pm2_5, pm10, no2, aqi);
    else begin
      $display("   3: PM2.5=%3d, PM10=%3d, NO2=%3d |    0    |  %3d   | FAIL", pm2_5, pm10, no2, aqi);
      errors = errors + 1;
    end

    // Test Case 4:
    // pm2_5 = 255, pm10 = 200, no2 = 100.
    // max = 255, min = 100, sum = 555.
    // numerator = 255*128 + 100*77 + 555*51 = 32640 + 7700 + 28305 = 68645.
    // AQI = 68645 / 256 = 268.
    pm2_5 = 8'd255;  pm10 = 8'd200;  no2 = 8'd100;
    #10;
    if (aqi == 16'd268)
      $display("   4: PM2.5=%3d, PM10=%3d, NO2=%3d |   268   |  %3d   | PASS", pm2_5, pm10, no2, aqi);
    else begin
      $display("   4: PM2.5=%3d, PM10=%3d, NO2=%3d |   268   |  %3d   | FAIL", pm2_5, pm10, no2, aqi);
      errors = errors + 1;
    end

    // Test Case 5:
    // pm2_5 = 123, pm10 = 45, no2 = 67.
    // max = 123, min = 45, sum = 235.
    // numerator = 123*128 + 45*77 + 235*51 = 15744 + 3465 + 11985 = 31194.
    // AQI = 31194 / 256 = 121.
    pm2_5 = 8'd123;  pm10 = 8'd45;  no2 = 8'd67;
    #10;
    if (aqi == 16'd121)
      $display("   5: PM2.5=%3d, PM10=%3d, NO2=%3d |   121   |  %3d   | PASS", pm2_5, pm10, no2, aqi);
    else begin
      $display("   5: PM2.5=%3d, PM10=%3d, NO2=%3d |   121   |  %3d   | FAIL", pm2_5, pm10, no2, aqi);
      errors = errors + 1;
    end

    $display("-------------------------------------");
    if (errors == 0)
      $display("All tests passed");
    else
      $display("Some tests failed");

    $finish;
  end

