`timescale 1ns/1ps
module tb_solar_radiation_average;

  // Testbench signals for inputs and output.
  reg [7:0] r0, r1, r2, r3, r4, r5, r6, r7;
  wire [7:0] avg_radiation;

  // Error counter (simulation only).
  integer errors;
  integer expected;

  // Instantiate the Unit Under Test (UUT)
  solar_radiation_average uut (
    .r0(r0), .r1(r1), .r2(r2), .r3(r3), .r4(r4), .r5(r5), .r6(r6), .r7(r7),
    .avg_radiation(avg_radiation)
  );

  initial begin
    errors = 0;

    $display("==========Testbench results==========");
    $display("=====================================");
    $display(" Test Input                                 | Expected | Output | Pass/Fail ");
    $display("-------------------------------------");

    // Test Case 1: All zeros.
    r0 = 8'd0;  r1 = 8'd0;  r2 = 8'd0;  r3 = 8'd0;
    r4 = 8'd0;  r5 = 8'd0;  r6 = 8'd0;  r7 = 8'd0;
    expected = 0; // (0+0+...+0)/8 = 0
    #10;
    if (avg_radiation == expected)
      $display("   1:  0, 0, 0, 0, 0, 0, 0, 0               |   %3d    |   %3d   | PASS", expected, avg_radiation);
    else begin
      $display("   1:  0, 0, 0, 0, 0, 0, 0, 0               |   %3d    |   %3d   | FAIL", expected, avg_radiation);
      errors = errors + 1;
    end

    // Test Case 2: All maximum values (255).
    r0 = 8'd255; r1 = 8'd255; r2 = 8'd255; r3 = 8'd255;
    r4 = 8'd255; r5 = 8'd255; r6 = 8'd255; r7 = 8'd255;
    expected = 255; // (8*255=2040, 2040/8 = 255)
    #10;
    if (avg_radiation == expected)
      $display("   2:255,255,255,255,255,255,255,255       |   %3d    |   %3d   | PASS", expected, avg_radiation);
    else begin
      $display("   2:255,255,255,255,255,255,255,255       |   %3d    |   %3d   | FAIL", expected, avg_radiation);
      errors = errors + 1;
    end

    // Test Case 3: 10, 20, 30, 40, 50, 60, 70, 80.
    r0 = 8'd10;  r1 = 8'd20;  r2 = 8'd30;  r3 = 8'd40;
    r4 = 8'd50;  r5 = 8'd60;  r6 = 8'd70;  r7 = 8'd80;
    expected = 45; // (10+20+30+40+50+60+70+80 = 360; 360/8 = 45)
    #10;
    if (avg_radiation == expected)
      $display("   3:10,20,30,40,50,60,70,80               |   %3d    |   %3d   | PASS", expected, avg_radiation);
    else begin
      $display("   3:10,20,30,40,50,60,70,80               |   %3d    |   %3d   | FAIL", expected, avg_radiation);
      errors = errors + 1;
    end

    // Test Case 4: 1, 2, 3, 4, 5, 6, 7, 8.
    r0 = 8'd1;   r1 = 8'd2;   r2 = 8'd3;   r3 = 8'd4;
    r4 = 8'd5;   r5 = 8'd6;   r6 = 8'd7;   r7 = 8'd8;
    expected = 4;  // (1+2+3+4+5+6+7+8 = 36; 36/8 = 4 when using integer division)
    #10;
    if (avg_radiation == expected)
      $display("   4: 1, 2, 3, 4, 5, 6, 7, 8               |   %3d    |   %3d   | PASS", expected, avg_radiation);
    else begin
      $display("   4: 1, 2, 3, 4, 5, 6, 7, 8               |   %3d    |   %3d   | FAIL", expected, avg_radiation);
      errors = errors + 1;
    end

    // Test Case 5: 100, 110, 120, 130, 140, 150, 160, 170.
    r0 = 8'd100; r1 = 8'd110; r2 = 8'd120; r3 = 8'd130;
    r4 = 8'd140; r5 = 8'd150; r6 = 8'd160; r7 = 8'd170;
    expected = 135; // (100+110+120+130+140+150+160+170 = 1080; 1080/8 = 135)
    #10;
    if (avg_radiation == expected)
      $display("   5:100,110,120,130,140,150,160,170         |   %3d    |   %3d   | PASS", expected, avg_radiation);
    else begin
      $display("   5:100,110,120,130,140,150,160,170         |   %3d    |   %3d   | FAIL", expected, avg_radiation);
      errors = errors + 1;
    end

    $display("-------------------------------------");
    if (errors == 0)
      $display("All tests passed");
    else
      $display("Some tests failed");

    $finish;
  end

